window.__finlexDocLoaded(10173,{"id":10173,"articles":[{"id":1000723,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Unified risk-based standard replacing legacy estimates/fair value/derivatives standards, requiring auditors to test management's process, develop an independent expectation, or review subsequent events, with heightened scrutiny of third-party pricing sources.","seq":0},{"id":1000724,"no":"AS 2501.07–.30","heading":"Three Substantive Approaches, Management Bias & Pricing Services","text":"• Three Testing Approaches (AS 2501.07): (1) Test the company's process (methods, data, significant assumptions); (2) Develop an independent expectation; (3) Evaluate audit evidence from events/transactions occurring after the measurement date.\n• Third-Party Pricing Sources (Appendix A): Specific reliability procedures for pricing services and broker quotes used in ASC 820 fair value measurements.","seq":1},{"id":1000725,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Converged in risk-based philosophy with ISA 540 (Revised) and China's CSA 1321.","seq":2},{"id":1000726,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
